class Solution {
    public: vector<int> busiestServers(int k,vector<int>& arrival,vector<int>& load){
        set<int> available;
        for(int server=0;server<k;++server)available.insert(server);
        priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> busy;
        vector<int> count(k);
        for(int i=0;i<(int)arrival.size();++i){
            while(!busy.empty()&&busy.top().first<=arrival[i]){
                available.insert(busy.top().second);
                busy.pop();
            }
            if(available.empty())continue;
            auto it=available.lower_bound(i%k);
            if(it==available.end())it=available.begin();
            int server=*it;
            available.erase(it);
            ++count[server];
            busy.push({
                (long long)arrival[i]+load[i],server
            });
        }
        int maximum=*max_element(count.begin(),count.end());
        vector<int> answer;
        for(int server=0;server<k;++server)if(count[server]==maximum)answer.push_back(server);
        return answer;
    }
};
